-- Новая программа тренировок: «Full body ягодичный мост» (12 тренировок).
--
-- Программа целиком живёт в program_templates (см. mergeTemplates в src/App.jsx).
-- Зашитые FOLDERS/PROGRAMS_MAP в src/programs.js НЕ трогаем: они запасной
-- вариант только для первых четырёх программ.
--
-- key задан по правилу slugifyKey из App.jsx и НЕ меняется никогда: за него
-- держатся profiles.program и префикс названий в workouts («{key} — тренировка N»).
-- Переименование программы — только через display_name.

-- 1. Колонки иконки и описания (идемпотентно: их могла уже завести миграция
--    2026-08-28_program_bulgarian_split.sql).
alter table program_templates add column if not exists icon        text;
alter table program_templates add column if not exists description text;

-- 2. Единственное упражнение, которого ещё не было в каталоге.
insert into catalog_exercises (name, muscle_group, equipment, type, hidden)
values ('Приседания плие с гантелей', 'Ноги', 'Гантели', 'compound', false)
on conflict (name) do nothing;

-- 3. Сама программа. sort — в конец списка программ.
--    Подходы без веса записаны как «× 20» — это принятая в шаблонах запись
--    собственного веса (parseTemplateSets отдаёт templateKg = null). «0 кг × 20»
--    писать НЕЛЬЗЯ: ноль пройдёт как настоящий вес и обнулит расчёт 1ПМ.
